"""Validate an independent restricted-zone survey before Native construction.

The packet is an input to local capture, never a worker assertion that a zone is
legally effective. Every asserted source is copied and hash checked at capture.
"""

import hashlib
import json
from pathlib import Path


ROLES = ("zone_sign", "zone_authority", "zone_boundaries", "effective_conditions",
         "stopping_exclusions", "subject_vehicle_class", "driver_identity",
         "entrant_vehicle_class", "entrant_parking_task", "passenger_exchange_method")


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def validate(path, case_id, plan):
    path = Path(path).resolve()
    packet = json.loads(path.read_text())
    if packet.get("case_id") != case_id or packet.get("cell_id") != "C135087":
        raise ValueError("reviewed site case/cell mismatch")
    if packet.get("map_id") != plan.map_id:
        raise ValueError("reviewed site map mismatch")
    if packet.get("restricted_purpose") != plan.restricted_purpose:
        raise ValueError("reviewed restricted purpose mismatch")
    for key in ("zone_start_m", "zone_end_m"):
        if packet.get(key) != getattr(plan, key):
            raise ValueError("reviewed zone boundary mismatch")
    sources = packet.get("sources")
    if not isinstance(sources, dict) or set(sources) != set(ROLES):
        raise ValueError("reviewed site source roles incomplete")
    for role, item in sources.items():
        if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
            raise ValueError("reviewed site source reference incomplete: " + role)
        source = Path(item["path"])
        if not source.is_absolute():
            source = path.parent / source
        source = source.resolve()
        if not source.is_file() or sha(source) != item["sha256"]:
            raise ValueError("reviewed site source missing or stale: " + role)
    if not packet.get("reviewer") or not packet.get("reviewed_at"):
        raise ValueError("independent site review identity missing")
    return packet

"""Source-bound audit of an original 20 Hz Native restricted-zone history."""

import hashlib
import json
import math
from pathlib import Path


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def audit_original_frames(frames_path: Path, context_path: Path, seal_path: Path,
                          case_id: str, expected_frames: int = 900) -> dict:
    """Reject absent/stale original sources; return measurements, never a verdict."""
    frames_path, context_path, seal_path = map(Path, (frames_path, context_path, seal_path))
    for path in (frames_path, context_path, seal_path):
        if not path.is_file():
            raise ValueError(f"missing original source: {path.name}")
    seal = json.loads(seal_path.read_text())
    context = json.loads(context_path.read_text())
    if seal.get("case_id") != case_id or context.get("case_id") != case_id:
        raise ValueError("case identity mismatch")
    if seal.get("frames_sha256") != _sha(frames_path) or seal.get("context_sha256") != _sha(context_path):
        raise ValueError("original source hash mismatch")
    for key in ("zone_start_m", "zone_end_m", "restricted_purpose", "restricted_source",
                "effective_conditions", "subject_vehicle_class_source", "driver_identity_source",
                "entrant_parking_purpose_source", "prohibited_stopping_exclusions_review"):
        if not context.get(key):
            raise ValueError(f"missing source-backed context: {key}")
    lo, hi = float(context["zone_start_m"]), float(context["zone_end_m"])
    if not lo < hi:
        raise ValueError("invalid zone boundaries")
    frames = [json.loads(line) for line in frames_path.read_text().splitlines() if line]
    if len(frames) != expected_frames:
        raise ValueError("incomplete original frame history")
    required = ("frame", "time_s", "subject_station_m", "subject_speed_mps",
                "entrant_station_m", "entrant_speed_mps", "entrant_waiting",
                "passenger_exchange_active", "passenger_station_m", "passenger_boarding_state",
                "entrant_access_blocked",
                "entrant_parking_task_active")
    for index, frame in enumerate(frames):
        if any(key not in frame for key in required):
            raise ValueError("missing original-frame observation")
        if frame["frame"] != index:
            raise ValueError("noncontiguous original frames")
        t = float(frame["time_s"])
        if not math.isfinite(t) or abs(t - index / 20.0) > 0.002:
            raise ValueError("original frame time mismatch")
        for key in ("subject_station_m", "subject_speed_mps", "entrant_station_m", "entrant_speed_mps", "passenger_station_m"):
            if not math.isfinite(float(frame[key])):
                raise ValueError("nonfinite original-frame measurement")
    inside = [f for f in frames if lo <= f["subject_station_m"] <= hi and f["subject_speed_mps"] < 0.1]
    exchange = [f for f in frames if f["passenger_exchange_active"]]
    states = {f["passenger_boarding_state"] for f in frames}
    if not {"approaching", "boarding", "aboard"}.issubset(states):
        raise ValueError("actual passenger exchange state transition absent")
    approaching = [f for f in frames if f["entrant_parking_task_active"] and f["entrant_station_m"] < lo]
    waiting = [f for f in frames if f["entrant_waiting"]]
    blocked = [f for f in frames if f["entrant_access_blocked"]]
    if not inside or not exchange or not approaching:
        raise ValueError("required zone, exchange or restricted-purpose approach absent")
    return {
        "case_id": case_id,
        "frames_sha256": _sha(frames_path),
        "context_sha256": _sha(context_path),
        "frame_count": len(frames),
        "fixed_context": {key: context[key] for key in (
            "zone_start_m", "zone_end_m", "restricted_purpose", "restricted_source",
            "effective_conditions", "subject_vehicle_class_source", "driver_identity_source",
            "entrant_parking_purpose_source", "prohibited_stopping_exclusions_review")},
        "subject_stationary_in_zone_frames": len(inside),
        "passenger_exchange_frames": len(exchange),
        "passenger_boarding_states": sorted(states),
        "entrant_approach_frames": len(approaching),
        "entrant_waiting_frames": len(waiting),
        "entrant_access_blocked_frames": len(blocked),
        "first_waiting_time_s": waiting[0]["time_s"] if waiting else None,
        "first_access_blocked_time_s": blocked[0]["time_s"] if blocked else None,
        "legal_interference": "unresolved_judgment",
        "legal_about_to_enter": "unresolved_judgment",
        "legal_temporary": "unresolved_judgment",
    }


def compare_cases(left: dict, right: dict) -> dict:
    """Verify source-backed fixed setup and report observed differences only."""
    if left.get("case_id") == right.get("case_id") or not left.get("case_id") or not right.get("case_id"):
        raise ValueError("distinct exact case identities required")
    if left.get("frame_count") != 900 or right.get("frame_count") != 900:
        raise ValueError("complete original histories required")
    if not left.get("frames_sha256") or not right.get("frames_sha256"):
        raise ValueError("sealed original source references required")
    if not left.get("fixed_context") or left["fixed_context"] != right.get("fixed_context"):
        raise ValueError("fixed zone, purpose or participant source differs")
    return {
        "case_ids": [left["case_id"], right["case_id"]],
        "fixed_context_source_matched": True,
        "observed_difference": {
            key: [left[key], right[key]] for key in (
                "entrant_waiting_frames", "entrant_access_blocked_frames",
                "passenger_exchange_frames", "subject_stationary_in_zone_frames")
        },
        "legal_comparison": "unresolved_judgment",
    }

"""Source-bound external pixel review of a restricted-zone Native attempt.

Physical completion means the listed phenomena were independently seen in
original pixels. This audit makes no statutory interference determination.
"""

import hashlib
import json
import subprocess
from pathlib import Path

from saved_audit import VIEWS, audit as audit_saved


OBSERVATIONS = ("restricted_zone_sign", "zone_boundaries", "passenger_vehicle",
                "passenger_exchange", "restricted_purpose_entrant", "entrant_approach",
                "entrant_waiting_or_access", "subject_zone_dwell", "four_camera_visibility")


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _decode_media(attempt):
    """Decode every selected encoded frame; source PNG custody is checked separately."""
    counts = {}
    for name in (*VIEWS, "raw"):
        media = attempt / (name + ".mkv")
        probe = subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0",
                                "-show_entries", "stream=width,height,avg_frame_rate",
                                "-of", "json", str(media)], capture_output=True, text=True)
        if probe.returncode:
            raise ValueError("encoded media probe failed: " + name)
        streams = json.loads(probe.stdout).get("streams", [])
        if len(streams) != 1 or streams[0].get("width", 0) <= 0 or streams[0].get("height", 0) <= 0:
            raise ValueError("encoded media video stream invalid: " + name)
        decoded = subprocess.run(["ffmpeg", "-v", "error", "-i", str(media),
                                  "-map", "0:v:0", "-progress", "pipe:1", "-nostats",
                                  "-f", "null", "-"],
                                 capture_output=True, text=True)
        if decoded.returncode:
            raise ValueError("encoded media full decode failed: " + name)
        frames = [int(line.partition("=")[2]) for line in decoded.stdout.splitlines()
                  if line.startswith("frame=")]
        if not frames or frames[-1] != 900:
            raise ValueError("encoded media frame count mismatch: " + name)
        counts[name] = frames[-1]
    return counts


def audit(attempt, case_id, expected_site_sha256, review_path, expected_review_sha256):
    attempt = Path(attempt).resolve()
    review_path = Path(review_path).resolve()
    if attempt == review_path or attempt in review_path.parents:
        raise ValueError("independent reviewer packet must be outside attempt")
    if not review_path.is_file() or not expected_review_sha256 or _sha(review_path) != expected_review_sha256:
        raise ValueError("independent reviewer packet missing or stale")
    saved = audit_saved(attempt, case_id, expected_site_sha256)
    if saved["diagnostic_fixture"]:
        raise ValueError("diagnostic fixture cannot satisfy original delivery")
    decoded_media = _decode_media(attempt)
    review = json.loads(review_path.read_text())
    if review.get("case_id") != case_id or review.get("site_packet_sha256") != expected_site_sha256:
        raise ValueError("external reviewer case/site mismatch")
    if not review.get("reviewer") or not review.get("reviewed_at"):
        raise ValueError("external reviewer identity missing")
    observations = review.get("observations")
    if not isinstance(observations, dict) or set(observations) != set(OBSERVATIONS):
        raise ValueError("physical observation review incomplete")
    history = [json.loads(line) for line in (attempt / "original-attempt/history.jsonl").read_text().splitlines()]
    for topic, item in observations.items():
        if not isinstance(item, dict) or item.get("observed") is not True or not item.get("note"):
            raise ValueError("physical observation unconfirmed: " + topic)
        index, view = item.get("frame"), item.get("view")
        if type(index) is not int or not 0 <= index < 900 or view not in VIEWS:
            raise ValueError("physical observation frame/view invalid: " + topic)
        if history[index]["camera_sources"][view]["sha256"] != item.get("pixel_sha256"):
            raise ValueError("physical observation pixel citation stale: " + topic)
    return {"case_id": case_id, "site_packet_sha256": expected_site_sha256,
            "review_sha256": expected_review_sha256, "observed_topics": list(OBSERVATIONS),
            "encoded_media": decoded_media,
            "physical_completion": True, "legal_status": "unresolved_judgment"}
